<?php $title = $recipe['title']; $currentUser = $auth?->getCurrentUser(); $jsonLd = ['@context' => 'https://schema.org', '@type' => 'Recipe', 'name' => $recipe['title'], 'description' => $recipe['description'], 'recipeIngredient' => array_map(static fn(array $ingredient): string => trim(format_quantity((float) ($ingredient['quantity'] ?? 0)) . ' ' . ($ingredient['unit'] ?? '') . ' ' . ($ingredient['name'] ?? '') . ' ' . ($ingredient['preparation'] ?? '')), $recipe['ingredients'] ?? []), 'recipeInstructions' => array_values($recipe['steps'] ?? [])]; ?><article class="container recipe-page<?= !empty($printMode) ? ' print-mode' : '' ?>"><?php if (!empty($flagStatus['active_count']) && $flagStatus['active_count'] === 1 && empty($blocked)): ?><div class="notice notice-warning">This recipe has been flagged and is awaiting review. Use your judgement.</div><?php endif; ?><?php if (!empty($blocked)): ?><div class="notice notice-danger">This recipe is temporarily unavailable while moderators review it.</div><?php endif; ?><header class="recipe-header"><div><p class="eyebrow"><?= e(implode(' • ', $recipe['categories'] ?? [])) ?></p><h1><?= e($recipe['title']) ?></h1><p class="lede"><?= e($recipe['description']) ?></p><div class="meta-row"><span>By <a href="/user/<?= e($author['username'] ?? 'unknown') ?>"><?= e($author['display_name'] ?? $author['username'] ?? 'Unknown') ?></a></span><span>Published <?= e(format_datetime((int) ($recipe['created_at'] ?? 0))) ?></span><span>★ <?= e(number_format((float) ($ratingStats['avg'] ?? 0), 1)) ?> (<?= e((string) ($ratingStats['count'] ?? 0)) ?> ratings)</span></div></div><div class="recipe-actions no-print"><a class="button button-secondary" href="/recipe/<?= e($recipe['id']) ?>/print">Print</a><?php if ($currentUser && ($currentUser['id'] === $recipe['author_id'] || $auth->hasRole('editor'))): ?><a class="button" href="/recipe/<?= e($recipe['id']) ?>/edit">Edit</a><?php endif; ?></div></header><div class="recipe-gallery"><?php if (!empty($recipe['images'])): ?><?php foreach ($recipe['images'] as $image): ?><img src="<?= e('/uploads/' . $image) ?>" alt="<?= e($recipe['title']) ?>"><?php endforeach; ?><?php else: ?><img src="/assets/img/placeholder.svg" alt="Recipe placeholder image"><?php endif; ?></div><section class="recipe-controls no-print"><div><label for="desired-servings">Desired servings</label><input id="desired-servings" type="number" min="1" value="<?= e((string) ($recipe['servings'] ?? 1)) ?>" data-original-servings="<?= e((string) ($recipe['servings'] ?? 1)) ?>"></div><div><span>Units</span><div class="button-group"><button type="button" class="button button-secondary" data-unit-toggle="us">US</button><button type="button" class="button button-secondary" data-unit-toggle="metric">Metric</button></div></div></section><div class="recipe-layout"><section><h2>Ingredients</h2><ul class="ingredient-list" data-recipe-servings="<?= e((string) ($recipe['servings'] ?? 1)) ?>"><?php foreach ($recipe['ingredients'] as $ingredient): ?><li data-ingredient data-quantity="<?= e((string) ($ingredient['quantity'] ?? '')) ?>" data-unit="<?= e((string) ($ingredient['unit'] ?? '')) ?>" data-name="<?= e((string) ($ingredient['name'] ?? '')) ?>"><span class="ingredient-amount"><?= e(format_quantity($ingredient['quantity'] ?? '')) ?></span> <span class="ingredient-unit"><?= e((string) ($ingredient['unit'] ?? '')) ?></span> <span class="ingredient-name"><?= e((string) ($ingredient['name'] ?? '')) ?></span><?php if (!empty($ingredient['preparation'])): ?><span class="muted">, <?= e($ingredient['preparation']) ?></span><?php endif; ?></li><?php endforeach; ?></ul></section><section><h2>Method</h2><ol class="step-list"><?php foreach ($recipe['steps'] as $step): ?><li><?= nl2br(e($step)) ?></li><?php endforeach; ?></ol><div class="tag-list"><?php foreach ($recipe['tags'] ?? [] as $tag): ?><a class="tag" href="/search?tags=<?= urlencode($tag) ?>"><?= e($tag) ?></a><?php endforeach; ?></div></section></div><section class="recipe-feedback no-print"><?php if ($auth->isLoggedIn()): ?><h2>Your rating</h2><?php include TEMPLATES_PATH . '/partials/star-rating.php'; ?><form action="/recipe/<?= e($recipe['id']) ?>/flag" method="post" class="inline-form flag-form"><?= \App\Util\Csrf::field() ?><label><span class="sr-only">Flag reason</span><select name="reason"><option value="copyright">Copyright concern</option><option value="spam">Spam</option><option value="unsafe">Unsafe / misleading</option><option value="offensive">Offensive</option><option value="other">Other</option></select></label><input name="details" type="text" placeholder="Optional details"><button class="button button-danger" type="submit">Flag recipe</button></form><?php else: ?><p><a href="/login">Log in</a> to rate or flag this recipe.</p><?php endif; ?></section></article><script type="application/ld+json"><?= json_encode($jsonLd, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) ?></script>
